import sys, heapq
from collections import defaultdict

def island(s):
    from collections import deque
    L=s.split("\n"); m,n=map(int,L[0].split()); g=L[1:1+m]; r,c=map(int,L[1+m].split()); Z=int(L[2+m])
    D=[[0]*n for _ in range(m)]; q=deque()
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
        a,b=r+dr,c+dc
        if 0<=a<m and 0<=b<n and g[a][b]=='.' and not D[a][b]: D[a][b]=1; q.append((a,b))
    best=-1
    while q:
        a,b=q.popleft()
        if any(0<=a+x<m and 0<=b+y<n and g[a+x][b+y]=='*' for x,y in ((1,0),(-1,0),(0,1),(0,-1))): best=D[a][b]; break
        for x,y in ((1,0),(-1,0),(0,1),(0,-1)):
            u,v=a+x,b+y
            if 0<=u<m and 0<=v<n and g[u][v]=='.' and not D[u][v]: D[u][v]=D[a][b]+1; q.append((u,v))
    if best<0: return "unreachable"
    cost=best*(best+1)
    return str(Z-cost) if cost<=Z else f"died {cost-Z}"

print(island(sys.stdin.read()))

